"""Creator 6.6 candidate-generation brief with live original research refresh."""
from __future__ import annotations
import json, subprocess, sys
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
PREFLIGHT=ROOT/'data/live/editorial_preflight.json'; NEWS=ROOT/'data/live/news_snapshot.json'; CONTEXT=ROOT/'data/live/publication_context.json'; CORE=ROOT/'data/live/superhuman_creator_core.json'; NOTES=ROOT/'docs/BINANCE_SQUARE_TOP_CREATOR_DEEP_RESEARCH_NOTES.md'; RESEARCH=ROOT/'data/live/original_research.json'
def load(p):
    try:
        x=json.loads(p.read_text(encoding='utf-8')); return x if isinstance(x,dict) else {}
    except Exception:return {}
def refresh_research():
    proc=subprocess.run([sys.executable,str(ROOT/'src/original_research_engine.py')],capture_output=True,text=True)
    if proc.stdout:print(proc.stdout,end='')
    if proc.stderr:print(proc.stderr,end='',file=sys.stderr)
    if proc.returncode: raise SystemExit(proc.returncode)
def main():
    refresh_research()
    p=load(PREFLIGHT); d=p.get('content_director_4') or {}; s=p.get('script_director_4') or {}; news=load(NEWS); ctx=load(CONTEXT); core=load(CORE); research=load(RESEARCH)
    fmt=str(d.get('recommended_format') or 'TOP MOVERS'); sym=str(ctx.get('symbol') or s.get('primary_symbol') or (d.get('primary_story') or {}).get('symbol','')).upper().replace('USDT','').replace('$','').strip(); selected=p.get('selected_opportunity') or {}; story=d.get('primary_story') or {}; narrative=str(d.get('narrative_engine') or s.get('narrative_engine') or 'what_to_watch'); archetype=str(s.get('creator_archetype') or 'conversational'); hooks=s.get('hook_candidates') or []
    if not sym: raise SystemExit('Candidate generation: authoritative asset missing')
    news_context=[]
    for article in (news.get('articles') or [])[:12]:
        if isinstance(article,dict): news_context.append({'title':article.get('title'),'source':article.get('source'),'url':article.get('url'),'published_at':article.get('published_at'),'summary':str(article.get('summary') or '')[:500],'symbols':article.get('symbols') or [],'news_score':article.get('news_score')})
    primary_news=bool(selected.get('news_title') or ctx.get('news_title')); directives='\n'.join('- '+str(x) for x in (core.get('generation_directives') or [])); redteam='\n'.join('- '+str(x) for x in (core.get('red_team_questions') or [])); standard=json.dumps(core.get('minimum_publish_standard') or {},ensure_ascii=False)
    try: research_notes=NOTES.read_text(encoding='utf-8')[:24000]
    except Exception: research_notes=''
    prompt={'version':'6.6','superhuman_core_version':core.get('version','1.0'),'symbol':sym,'format':fmt,'narrative_engine':narrative,'creator_archetype':archetype,'authoritative_context':ctx,'original_research':research,'primary_story':story,'selected_opportunity':selected,'fresh_news':news_context[:12],'research_notes_loaded':bool(research_notes),'instruction':f'''You are the senior editorial intelligence system for a world-class Binance Square creator. Discover an original, evidence-backed insight that a serious reader would not get from a basic news recap.\n\nSUPERHUMAN CORE:\n{directives}\n\nRED-TEAM:\n{redteam}\n\nMINIMUM STANDARD: {standard}\n\nDEEP RESEARCH PLAYBOOK:\n{research_notes}\n\nLIVE ORIGINAL RESEARCH:\n{json.dumps(research,ensure_ascii=False)}\n\nFIRST: reason privately about 5 genuinely different theses, not 5 wordings. Prefer the strongest information advantage, evidence, tension, consequence and reader usefulness. Use anomalies, relationships, mechanisms, contradictions, comparisons and follow-ups from the research artifact. If evidence is insufficient, choose RESEARCH/WAIT rather than inventing facts.\n\nTHEN: create 5 genuinely different finished candidates: strongest format; evidence/data; mechanism; counterpoint/risk; concise high-energy. At least one hidden mechanism, one challenge to the obvious narrative, and one reusable mental model.\n\nCONTENT STANDARD: complete specific hook; 1-3 strongest supplied facts; non-obvious interpretation; meaningful counterpoint/invalidation; concrete confirmation/change-my-view signal; exactly ONE genuine question. No generic engagement bait.\n\nHUMAN QUALITY: varied sentence lengths, natural rhythm, precise verbs, recognizable POV. Never fabricate personal experience, trades, profits, conversations, emotions or facts. Avoid corporate filler, emoji stacks, repetitive transitions and sterile AI phrasing.\n\nORIGINALITY: if the ticker can be swapped and the post still works, fail it. Headline-only summaries fail. Prefer verified relationships, mechanisms, contradictions, comparisons and reusable frameworks.\n\nEVIDENCE: only supplied verified evidence. Never invent prices, volume, sources, headlines, targets, liquidations, ETF flows, whale activity or outcomes. Keep hypotheses conditional.\n\nVISUAL: specify exactly what the visual should prove or clarify; never decorative logos when a truthful data visual is available.\n\nNEWS: explain the verified event and why it matters without copying the headline. Use natural attribution; no duplicate Source lines.\n\nBefore selecting the winner, red-team all five. If none clears the standard, return WAIT rather than forcing publication.''','selection_criteria':['information_advantage','thesis_strength','stop_scroll_strength','evidence_density','specificity','reader_value','originality','why_now clarity','usefulness','conversation_quality','mobile_readability','format_fidelity','visual_information_value','risk_discipline','anti_genericity','anti_ai_templating','natural_voice','research_playbook_alignment'],'hook_candidates':hooks}
    p['candidate_generation_4']=prompt; PREFLIGHT.write_text(json.dumps(p,indent=2,ensure_ascii=False),encoding='utf-8'); print(json.dumps({'status':'OK','version':'6.6','research':'refreshed','information_advantage':research.get('information_advantage_score'),'format':fmt,'symbol':sym,'candidate_count':5,'primary_news':primary_news},indent=2))
